Import ListNotations.
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.
Open Scope bv_scope.
Open Scope Z_scope.
Import SX2. Import SX2S.

Abbreviation RSEGS := Asan.M.loaded_segments.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Definition ABUF : Z := 0x6e4b40.

Definition apb_cells (w : Z) : list (Z * nat * Z) :=
  [(0x185600, 8%nat, 0x172dc0); (0x185608, 8%nat, 0x16cadc); (0x185780, 8%nat, 0x1750fc); (0x185788, 8%nat, 0x175500);
   (0x18f6f8, 8%nat, 0x7fff8000); (0x1903d8, 1%nat, 1); (0x1903d9, 1%nat, 1); (0x22127c, 1%nat, 1);
   (0x188140, 4%nat, 5);
   (0x188160, 8%nat, 0x6e4f40);
   (0x188168, 8%nat, w);
   (0x1881a0, 8%nat, 1024);
   (0x1881cc, 4%nat, 0xffffffff);
   (0x1881d0, 4%nat, 0xffffffff);
   (0x7fffaa10, 8%nat, 0); (0x800d4968, 8%nat, 0)]%Z.

Record apbH (mem : word -> option byte) (sp : word) (w can : Z) : Prop := APBH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : ASP_LO <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= ASP_HI;
  Pstk   : stk_ok RSEGS mem sp 3400;
  Pimg   : forall i, 0x10000 <= i < 0x91000 -> mem (Z_to_bv 64 i) = None;
  Pgot   : forall i, 0x17c000 <= i < 0x185000 -> mem (Z_to_bv 64 i) = None;
  Pcells : cells_ok mem (apb_cells w);
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0x6e3f58) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64;
  Psh0   : forall a, 2147450880 + (bv_unsigned sp - 4096) / 8 <= a < 2147450880 + bv_unsigned sp / 8 ->
             mem (Z_to_bv 64 a) = Some (Z_to_bv 8 0) }.

Definition apb_post `{fx : DFP} (regs : bvmap 5 word) (mem rom : word -> option byte) (sp : word) (w : Z) : Prop :=
  exists regs' mem',
    msteps RSEGS (mkst regs (Z_to_bv 64 0xe8c04) mem rom) (mkst regs' (Z_to_bv 64 0xe8b58) mem' rom)
    /\ keeps_cs regs regs'
    /\ frame_mod mem mem' [(Z_to_bv 64 (bv_unsigned sp - 3400), 3400); (Z_to_bv 64 0x188140, 4);
                          (Z_to_bv 64 0x188168, 8); (Z_to_bv 64 w, 2)]
    /\ rdn RSEGS mem' (Z_to_bv 64 w) 2 = Some [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]
    /\ rdn RSEGS mem' (Z_to_bv 64 0x188168) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 (w + 2)))
    /\ rdn RSEGS mem' (Z_to_bv 64 0x188140) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5)).

Definition apb_kn (w : Z) : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) ASP_LO ASP_HI;
   KWr (SA (EVar 0) (-3400)) 3400;
   KImg 0x10000 0x91000; KImg 0x17c000 0x185000;
   KWord (SA (ELit 0) 0x6e3f58) 8 (EVar 1);
   KWr (SA (ELit 0) 0x188140) 232; KWr (SA (ELit 0) 0x6e4b40) 1024;
   KRange ap1_shx ASH_LO ASH_HI; KZero (SA ap1_shx 0) (ELit 8)]%Z
  ++ kn_cells (apb_cells w).

Definition apb_regions (w : Z) : list sregion :=
  [(SA (EVar 0) (-3400), 3400); (SA (ELit 0) 0x188140, 4); (SA (ELit 0) 0x188168, 8); (SA (ELit 0) w, 2)].

Definition apb_run (w : Z) :=
  sym_exec RSEGS FUEL1 true STOPS1 scrA (SS 0xe8c04 ap1_sr [] (apb_kn w) 34) [].

Section Package.
  Context {fx : DFP}.
  Variables (regs : bvmap 5 word) (mem rom : word -> option byte) (sp : word) (w can : Z).
  Hypothesis PH : apbH mem sp w can.
  Hypothesis Hw : 0x6e4b40 <= w <= 0x6e4b44.
  Hypothesis R1 : getr regs 1 = Z_to_bv 64 0xe8b58.
  Hypothesis R2 : getr regs 2 = sp.
  Hypothesis R11 : getr regs 11 = Z_to_bv 64 0.

  Let E := ENV (p1_vals regs sp can).

  Lemma adenot_lit0 : forall k, 0 <= k < 2 ^ 64 -> adenot E (SA (ELit 0) k) = Z_to_bv 64 k.
Proof.
