  Lemma apb_case : forall ss' scs scr' kn' hs',
    apb_run w = (ss', scs, scr') ->
    s_pc ss' = 0xe8b58 ->
    log_covered (apb_regions w) (s_log ss') = true ->
    same_regs ap1_sr (s_regs ss') callee_saved = true ->
    carry (s_log ss') (apb_kn w) [] = (kn', [], hs') ->
